CREATE TABLE scope_snapshots (id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), versions_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE conversations (id TEXT PRIMARY KEY, title TEXT NOT NULL, project_id TEXT REFERENCES projects(id), created_at TEXT NOT NULL);
CREATE TABLE answer_runs (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations(id), scope_id TEXT NOT NULL REFERENCES scope_snapshots(id), question TEXT NOT NULL, mode TEXT NOT NULL, strategy TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id), status TEXT NOT NULL, result_json TEXT, error_code TEXT, created_at TEXT NOT NULL);
CREATE TABLE evidence_records (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, source_anchor_id TEXT NOT NULL, quote TEXT NOT NULL, anchor_json TEXT NOT NULL, human_status TEXT NOT NULL DEFAULT 'unreviewed', review_note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE claim_records (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES answer_runs(id), text TEXT NOT NULL, evidence_ids_json TEXT NOT NULL, source_status TEXT NOT NULL, model_support TEXT NOT NULL, comparability TEXT NOT NULL DEFAULT 'not_assessed', human_status TEXT NOT NULL DEFAULT 'unreviewed');
CREATE TABLE research_plans (id TEXT PRIMARY KEY, scope_id TEXT NOT NULL REFERENCES scope_snapshots(id), question TEXT NOT NULL, fields_json TEXT NOT NULL, mode TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE research_items (plan_id TEXT NOT NULL REFERENCES research_plans(id), doc_version_id TEXT NOT NULL REFERENCES document_versions(id), status TEXT NOT NULL, processed_chunks INTEGER NOT NULL DEFAULT 0, total_chunks INTEGER NOT NULL DEFAULT 0, observations_json TEXT NOT NULL DEFAULT '[]', error_code TEXT, PRIMARY KEY(plan_id,doc_version_id));
CREATE TABLE report_revisions (id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES research_plans(id), revision INTEGER NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(plan_id,revision));
CREATE TABLE human_reviews (id TEXT PRIMARY KEY, target_id TEXT NOT NULL, status TEXT NOT NULL, note TEXT NOT NULL, created_at TEXT NOT NULL);
